29	std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
30	  std::ifstream f(p);
31	  std::vector<std::string> lines;
32	  ok = static_cast<bool>(f);
33	  if (!ok) return lines;
34	  std::string line;
35	  while (std::getline(f, line)) lines.push_back(line);
36	  return lines;
37	}
