110	int list_fixtures() {
111	  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
112	  bool ok;
113	  std::vector<std::string> lines = read_lines(mk, ok);
114	  if (!ok) {
115	    std::fprintf(stderr, "andesim: missing %s\n", mk.c_str());
116	    return 2;
117	  }
118	  std::vector<Fixture> rows = parse_fixtures(lines);
119	
120	  size_t width = 0;
121	  for (const Fixture& r : rows) width = std::max(width, r.name.size());
122	
123	  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
124	  for (const Fixture& r : rows)
125	    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
126	  return 0;
127	}
